from .repository import existing_emails, put_contact

_CONTACT_FIELDS = frozenset({"email", "name"})

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(row, index):
    if not isinstance(row, dict):
        raise ValueError(f"row {index}: must be an object")
    if set(row) != _CONTACT_FIELDS:
        raise ValueError(f"row {index}: must have exactly the fields 'email' and 'name'")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError(f"row {index}: 'email' and 'name' must be strings")

    email = email.strip()
    name = name.strip()

    if email.count("@") != 1:
        raise ValueError(f"row {index}: email must contain exactly one '@'")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError(f"row {index}: email must have nonempty local and domain parts")
    if any(ch.isspace() for ch in email):
        raise ValueError(f"row {index}: email must not contain whitespace")
    if not name:
        raise ValueError(f"row {index}: name must not be empty")

    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")

    # Validate the complete batch before touching the database.
    batch = {}
    for index, row in enumerate(rows):
        email, name = _normalize_row(row, index)
        if email in batch:
            raise ValueError(f"row {index}: duplicate email in batch: {email}")
        batch[email] = name

    if not batch:
        return {"inserted": 0, "updated": 0}

    # One transaction: any failure rolls back, leaving all contacts unchanged.
    # BEGIN IMMEDIATE takes the write lock before the existence check so the
    # inserted/updated counts match what is actually written.
    with connection:
        connection.execute("BEGIN IMMEDIATE")
        existing = existing_emails(connection, batch)
        for email, name in batch.items():
            put_contact(connection, email, name)

    return {"inserted": len(batch) - len(existing), "updated": len(existing)}
